        programdata_account
            .data_as_mut_slice()
            .get_mut(UpgradeableLoaderState::size_of_programdata_metadata()..)
            .unwrap()
            .copy_from_slice(&elf);
        process_instruction(
            &loader_id,
            &instruction,
            vec![
                (programdata_address, programdata_account.clone()),
                (upgrade_authority_address, upgrade_authority_account.clone()),
